def classify(pressure):
    if pressure <= 0 or pressure > 2000:
        print("FAULT")
    elif pressure < 900:
        print("LOW")
    elif pressure <= 1100:
        print("NORMAL")
    else:
        print("HIGH")

def station_report(site, pressure, channels, days_since_calibration):
    if pressure <= 0 or pressure > 2000:
        grade = "FAULT"
    elif pressure < 900:
        grade = "LOW"
    elif pressure <= 1100:
        grade = "NORMAL"
    else:
        grade = "HIGH"

    if grade == "FAULT" or channels <= 0:
        status = "OFFLINE"
    elif days_since_calibration > 30 or channels < 3:
        status = "DEGRADED"
    else:
        status = "ONLINE"

    print("STATION REPORT")
    print("==============")
    print("Site:", site)
    print("Pressure:", pressure, grade)
    print("Channels:", channels)
    print()
    print("Status:", status)
    if status != "ONLINE":
        print("Action: CHECK THE STATION")
